import{_ as e,o as d,c as r,a2 as o}from"./chunks/framework.doxMM-x8.js";const T=JSON.parse('{"title":"API configuration","description":"","frontmatter":{"docLocale":"en","counterpart":"/reference/config","contentType":"reference","prev":false,"next":false},"headers":[],"relativePath":"en/reference/config.md","filePath":"en/reference/config.md"}'),a={name:"en/reference/config.md"};function n(c,t,i,s,l,_){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="api-configuration" tabindex="-1">API configuration <a class="header-anchor" href="#api-configuration" aria-label="Permalink to &quot;API configuration&quot;">​</a></h1><p>Node settings come directly from the running parser. See the <a href="./../guides/server-platform">platform guide</a> for usage. Production secrets never enter the documentation.</p><h2 id="current-lab-word-server" tabindex="-1">Current Lab Word Server <a class="header-anchor" href="#current-lab-word-server" aria-label="Permalink to &quot;Current Lab Word Server&quot;">​</a></h2><p>Defaults come from the running parser in <a href="https://github.com/CaiZongyuan/labworld/blob/3b75a1fe29ff5579361080121aec3b9b5c0fcc1c/apps/server/src/config.ts" target="_blank" rel="noreferrer">config.ts</a>. The development entrypoint and Vite read <code>WEB_PORT</code> and <code>VITE_API_PROXY</code>.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Secret</th><th>Description</th></tr></thead><tbody><tr><td><code>LAB_WORD_WEB_DIR</code></td><td></td><td>no</td><td>Built Web directory for production same-origin hosting; empty disables static hosting.</td></tr><tr><td><code>LAB_WORD_HOST</code></td><td>127.0.0.1</td><td>no</td><td>Bind hostname. APP_BIND is the compatibility fallback.</td></tr><tr><td><code>SERVER_PORT</code></td><td>3000</td><td>no</td><td>Listen port, integer 1–65535.</td></tr><tr><td><code>APP_ORIGIN</code></td><td><a href="http://127.0.0.1:5173" target="_blank" rel="noreferrer">http://127.0.0.1:5173</a></td><td>no</td><td>Trusted Web origin; HTTPS or loopback HTTP.</td></tr><tr><td><code>SESSION_ABSOLUTE_SECS</code></td><td>604800</td><td>no</td><td>Absolute session seconds, 60–2592000.</td></tr><tr><td><code>SESSION_IDLE_SECS</code></td><td>86400</td><td>no</td><td>Idle session seconds, 60 through absolute lifetime.</td></tr><tr><td><code>RATE_LIMIT_ENABLED</code></td><td>true</td><td>no</td><td>Enable local limits; true or false.</td></tr><tr><td><code>RATE_LIMIT_WINDOW_SECS</code></td><td>60</td><td>no</td><td>Integer 1–3600; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>RATE_LIMIT_MAX_LOCAL_ENTRIES</code></td><td>4096</td><td>no</td><td>Integer 1–100000; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>RATE_LIMIT_REGISTRATION</code></td><td>20</td><td>no</td><td>Integer 1–1000000; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>RATE_LIMIT_REGISTRATION_FALLBACK</code></td><td>5</td><td>no</td><td>Integer 1–1000000; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>RATE_LIMIT_AUTHENTICATION</code></td><td>60</td><td>no</td><td>Integer 1–1000000; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>RATE_LIMIT_AUTHENTICATION_FALLBACK</code></td><td>20</td><td>no</td><td>Integer 1–1000000; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>RATE_LIMIT_RESOURCE</code></td><td>600</td><td>no</td><td>Integer 1–1000000; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>RATE_LIMIT_RESOURCE_FALLBACK</code></td><td>120</td><td>no</td><td>Integer 1–1000000; quotas use TCP peer and fallback cannot exceed primary.</td></tr><tr><td><code>FILE_MAX_BYTES</code></td><td>20971520</td><td>no</td><td>Integer 1–104857600; streamed byte limit.</td></tr><tr><td><code>UPLOAD_SESSION_SECS</code></td><td>900</td><td>no</td><td>Integer 1–3600; capability lifetime in seconds.</td></tr><tr><td><code>DOWNLOAD_URL_SECS</code></td><td>60</td><td>no</td><td>Integer 1–300; capability lifetime in seconds.</td></tr><tr><td><code>FILE_PUBLIC_ORIGIN</code></td><td><a href="http://127.0.0.1:5173" target="_blank" rel="noreferrer">http://127.0.0.1:5173</a></td><td>no</td><td>Byte URL origin; defaults to trusted Web origin. HTTPS or loopback HTTP.</td></tr><tr><td><code>LAB_OBSERVATION_RETENTION_SECS</code></td><td>86400</td><td>no</td><td>Raw observation retention seconds (1–31536000). Current properties remain.</td></tr><tr><td><code>LAB_RECORD_RETENTION_SECS</code></td><td>2592000</td><td>no</td><td>Ended record retention seconds (1–31536000). Active Tasks remain.</td></tr><tr><td><code>LAB_WORD_DATA_DIR</code></td><td>data</td><td>no</td><td>Owned persistent DB, blobs and secrets directory. CONTRACT_DATA_DIRECTORY is the test fallback.</td></tr></tbody></table><p><a href="https://github.com/CaiZongyuan/labworld/blob/3b75a1fe29ff5579361080121aec3b9b5c0fcc1c/.env.example" target="_blank" rel="noreferrer">.env.example</a> lists current Node and Web settings. The ordinary service does not use legacy database, Redis or object-storage configuration. See <a href="./../guides/server-foundation">TypeScript service foundation</a> to start the server and Web.</p>',6)])])}const p=e(a,[["render",n]]);export{T as __pageData,p as default};
